<script lang="ts">
  export let resourceName = ''; export let accessMode: 'direct' | 'agent' = 'direct'; export let host = ''; export let database = ''; export let mcpServerName = ''; export let credentialConfigured = false; export let testBusy = false; export let testStatus = ''; export let testMessage = ''; export let testError = ''; export let testLatency = 0; export let onSubmit: () => void = () => {};
</script>
<form class="provider-summary docker-summary" on:submit|preventDefault={onSubmit}><div><span>PostgreSQL 资源</span><strong>{resourceName}</strong></div><div><span>接入方式</span><strong>{accessMode === 'agent' ? 'Agent · MCP 代理' : 'Direct · 直接连接'}</strong><small>{accessMode === 'agent' ? mcpServerName || '未选择 MCPServer' : `${host || '未设置主机'} · ${database || '未设置数据库'}`}</small></div><div><span>凭据</span><strong>{accessMode === 'agent' ? '由 MCPServer 管理' : credentialConfigured ? '已配置' : '未配置'}</strong></div><div><span>连接核验</span>{#if testBusy}<strong>正在测试连接...</strong>{:else if testStatus === 'succeeded'}<strong class="success">连接正常 · {testLatency} ms</strong><small>{testMessage}</small>{:else if testError}<strong class="failed">连接失败</strong><small>{testError}</small>{:else}<strong>尚未核验</strong>{/if}</div></form>
